test('morning configuration creates exact durations and one separate recess',()=>{const r=setup();r.run("globalThis.slots=templateSlots({center:'primaria',startTime:'08:45',sessionMinutes:50,morningSessions:5,breakAfter:2,breakMinutes:20})");assert.equal(r.box.slots.filter(s=>!s.recreo).length,5);assert.equal(r.box.slots[2].recreo,true);assert.equal(r.box.slots[0].end,'09:35');assert.equal(r.box.slots.at(-1).end,'13:15');for(const config of ["{sessionMinutes:0}","{morningSessions:2.5}","{morningSessions:2,breakAfter:3}","{startTime:'23:00',sessionMinutes:60}","{breakAfter:0,breakMinutes:30}"]){assert.throws(()=>r.run('templateSlots('+config+')'));}});
test('Drive delete requires confirmation, trashes rather than permanently deletes, and preserves local data',async()=>{const r=setup();r.run("cloud.user={email:'test'};cloud.fileId='f';cloud.projectId=state.projectId;globalThis.calls=[];gapi=async(url,options)=>{calls.push({url,options});return {};};");await r.run("cloudMenu([{id:'f',name:'Horario <x>',modifiedTime:'2026-10-28'}])");assert.doesNotMatch(r.elements.get('#mbox').innerHTML,/Ver en Drive/);assert.match(r.elements.get('#mbox').innerHTML,/data-trash-id="f"/);r.run("confirmDriveTrash('f')");assert.equal(r.box.calls.length,0);assert.match(r.elements.get('#mbox').innerHTML,/Sí, borrar de Drive/);assert.doesNotMatch(r.elements.get('#mbox').innerHTML,/<x>/);r.run('cancelDriveTrash()');await r.run('trashDriveProject()');assert.equal(r.box.calls.length,0);r.run("confirmDriveTrash('f');globalThis.before=JSON.stringify(state)");await r.run('trashDriveProject()');assert.equal(r.box.calls.length,1);assert.equal(r.box.calls[0].options.method,'PATCH');assert.equal(JSON.parse(r.box.calls[0].options.body).trashed,true);assert.equal(r.run('cloud.fileId'),null);assert.equal(r.run('JSON.stringify(state)'),r.box.before);});
test('failed Drive deletion retains the existing link; stale account confirmation cannot delete',async()=>{const r=setup();r.run("cloud.user={};cloud.fileId='f';driveMenuFiles=[{id:'f',name:'N',modifiedTime:'2026-10-28'}];gapi=async()=>{throw Error('sin permisos');};confirmDriveTrash('f')");await r.run('trashDriveProject()');assert.equal(r.run('cloud.fileId'),'f');assert.equal(r.run('cloud.deleting'),false);r.run("globalThis.writes=0;gapi=async()=>{writes++;};confirmDriveTrash('f');cloudEpoch++;");await r.run('trashDriveProject()');assert.equal(r.run('writes'),0);});
test('a pending deletion suppresses autosave and duplicate deletion requests',async()=>{const r=setup();r.run("cloud.user={};cloud.fileId='f';cloud.dirty=true;cloud.deleting=true;globalThis.writes=0;driveMetadata=async()=>{writes++;};pendingDriveTrash={id:'f',epoch:cloudEpoch};");await r.run('cloudSaveNow()');await r.run('trashDriveProject()');assert.equal(r.run('writes'),0);});
test('official primary baselines total 1350 teaching minutes per course and preserve Extremadura cycles',()=>{const r=setup();assert.equal(r.run('Array.from({length:6},(_,i)=>MURCIA_HOURS.reduce((n,row)=>n+row[1][i],0)).every(n=>n===1350)'),true);assert.equal(r.run('Array.from({length:6},(_,i)=>EXTREMADURA_HOURS.reduce((n,row)=>n+row[1][i],0)).every(n=>n===1350)'),true);assert.equal(r.run("EXTREMADURA_HOURS.find(row=>row[0].includes('Conocimiento'))[1][4]+EXTREMADURA_HOURS.find(row=>row[0].includes('Conocimiento'))[1][5]"),450);assert.equal(r.run("EXTREMADURA_HOURS.find(row=>row[0].includes('Valores'))[1][4]"),0);assert.equal(r.run("EXTREMADURA_HOURS.find(row=>row[0].includes('Valores'))[1][5]"),90);});
