for(const t of state.teachers)state.regulatory.teachers[t.id]={unit:'minutes',min:0,max:t.id==='t'?60:0,presenceMin:0,presenceMax:t.id==='t'?60:0,extraTeaching:0,extraPresence:0,source:'https://www.boe.es/',context:regulationContext(),reviewed:true,qualificationReviewed:true,subjectIds:t.id==='t'?['s']:[],teachingTypes:['clase']};
