test('privacy controls block erasure while a Drive write is in progress',()=>{const r=setup();r.run("cloud.saving=true;forgetLocalData()");assert.equal(r.run('state.teachers.length'),2);assert.match(r.box.lastToast,/termine la operación/);});

test('sign-out during token acquisition prevents a retry prompt and any API request',async()=>{const r=setup();r.run("globalThis.rejectToken=null;globalThis.tokenCalls=0;globalThis.networkCalls=0;getToken=()=>{tokenCalls++;return new Promise((resolve,reject)=>{rejectToken=reject;});};globalThis.fetch=async()=>{networkCalls++;return {ok:true};};");const req=r.run('gapi(DRIVE)'),checked=assert.rejects(req,/cancelada/);r.run("cloudSignOut();rejectToken(Error('Conexión cancelada'))");await checked;assert.equal(r.run('tokenCalls'),1);assert.equal(r.run('networkCalls'),0);});
test('failed Google component load remains optional and can be retried',async()=>{const r=runtime({protocol:'https:'});r.run(fixture);const scripts=[];r.box.document.createElement=()=>({remove(){}});r.box.document.head={appendChild:s=>scripts.push(s)};const loading=r.run('cloudSignIn()');scripts[0].onerror();await loading;assert.equal(r.run('googleIdentityPromise'),null);assert.equal(r.elements.get('#retryGooglePrivacy').hidden,false);assert.equal(r.run('cloud.token'),null);assert.match(r.elements.get('#googlePrivacyStatus').textContent,/seguir trabajando/);});

test('school course follows the current Madrid calendar year and offers five future courses',()=>{const r=setup();assert.equal(r.run("currentSchoolCourse(new Date('2026-01-01T12:00:00Z'))"),'2026-2027');assert.equal(r.run("currentSchoolCourse(new Date('2026-12-31T23:30:00Z'))"),'2027-2028');const html=r.run("schoolCourseOptions('',new Date('2026-10-29T12:00:00Z'))");assert.equal((html.match(/<option/g)||[]).length,6);assert.match(html,/value="2026-2027" selected>2026\/2027/);assert.match(html,/2031\/2032/);const old=r.run("schoolCourseOptions('2024-2025',new Date('2026-10-29T12:00:00Z'))");assert.match(old,/value="2024-2025" selected/);});
test('all course editors use a dropdown without replacing an existing saved course',()=>{const r=setup();r.run("state.course='2024-2025';fix();ui.view='inicio';render();");assert.match(r.elements.get('#view').innerHTML,/select[^>]+aria-label="Curso escolar"/);r.run("setupDraft={...initialSetupDraft('new'),region:'madrid'};renderSetup()");assert.match(r.elements.get('#mbox').innerHTML,/select[^>]+id="setupCourse"/);assert.match(r.run('vNormativa()'),/select[^>]+id="lawCourse"/);assert.equal(r.run('state.course'),'2024-2025');});
test('Ejemplo is next to Nuevo and asks for stage plus region before changing data',()=>{const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');assert.match(html,/onclick="newProject\(\)"[^>]*>Nuevo proyecto<\/button>\s*<button[^>]+onclick="exampleModal\(\)"/);const r=setup();r.run("globalThis.before=JSON.stringify(state);exampleModal()");assert.match(r.elements.get('#mbox').innerHTML,/id="exampleCenter"/);assert.match(r.elements.get('#mbox').innerHTML,/id="exampleRegion"/);assert.equal(r.run('JSON.stringify(state)'),r.box.before);assert.throws(()=>r.run("createExampleProject('primaria','')"),/comunidad/);});
test('every region has complete fictional Primary and Secondary data without legal claims',()=>{const r=setup();for(const center of ['primaria','secundaria']){r.run('globalThis.examples=REGIONS.map(r=>createExampleProject('+JSON.stringify(center)+',r.id))');for(const p of r.box.examples){assert.ok(p.teachers.length>=8);assert.ok(p.groups.every(g=>g.level&&g.studentCount>0));assert.ok(p.rooms.every(room=>room.cap>=30));assert.ok(p.activities.length>20);assert.equal(p.example.fictional,true);assert.equal(p.absences.length,1);assert.equal(p.course,r.run('currentSchoolCourse()'));assert.ok(Object.values(p.regulatory.teachers).every(c=>c.reviewed===false&&c.source===''));assert.ok(p.subjects.some(s=>s.curriculum?.region===p.region));}}});
test('both full example flows generate conflict-free, detached schedules with a recovery copy',async()=>{for(const center of ['primaria','secundaria']){const r=setup();r.run("cloud.fileId='real-file';cloud.user={};globalThis.before=JSON.stringify(state);exampleDraft={project:createExampleProject("+JSON.stringify(center)+",'galicia')};");await r.run('loadPreparedExample()');assert.equal(r.run('cloud.fileId'),null);assert.equal(r.run('state.lessons.filter(l=>l.day==null).length'),0,center+': '+r.box.lastToast);assert.equal(r.run('allIssues().size'),0,center);assert.equal(r.run('state.versions.length'),1);assert.equal(r.run('state.versions[0].snapshot.name'),r.run('state.name'));assert.equal(r.run('state.region'),'galicia');assert.ok(r.storage.has('maxhorario_recovery'));assert.equal(r.run('complianceReport().ok'),false);assert.doesNotThrow(()=>r.run('parseProject(state)'));}});
test('guidance has X, move controls, no sticky position and reappears for the next Ver action',()=>{const r=setup();r.run("fix();openComplianceTarget({kind:'teacher',id:'t',code:'contract'},'Revisa esto')");assert.match(r.elements.get('#mbox').innerHTML,/aria-label="Cerrar indicación"/);assert.match(r.elements.get('#mbox').innerHTML,/aria-label="Subir indicación"/);assert.match(r.elements.get('#mbox').innerHTML,/draggable="true"/);r.run('dismissComplianceGuidance()');assert.equal(r.run('complianceGuidance'),null);r.run("openComplianceTarget({kind:'teacher',id:'u',code:'contract'},'Otro aviso')");assert.match(r.elements.get('#mbox').innerHTML,/Otro aviso/);const css=fs.readFileSync(path.join(__dirname,'styles.css'),'utf8');assert.doesNotMatch(css,/#mbox>\.issue-guidance,#view>\.issue-guidance\{position:sticky/);assert.doesNotMatch(css,/border-left:4px solid #e97b8a/);});
test('vertical guidance movement reorders the panel in normal flow',()=>{const r=setup();r.run(`
complianceGuidance={position:0};
globalThis.parent={children:[],querySelector(){return panel;},insertBefore(el,next){this.children=this.children.filter(x=>x!==el);const i=next?this.children.indexOf(next):this.children.length;this.children.splice(i,0,el);}};
globalThis.panel={name:'panel',tagName:'DIV',parentElement:parent,matches:()=>false};
const make=name=>({name,tagName:'DIV',matches:()=>false,compareDocumentPosition(other){return parent.children.indexOf(this)<parent.children.indexOf(other)?4:2;}});
parent.children=[panel,make('first'),make('second')];globalThis.button={closest:()=>panel};moveGuidance(button,1);
`);assert.equal(r.run("parent.children.map(x=>x.name).join(',')"),'first,panel,second');assert.equal(r.run('complianceGuidance.position'),1);r.run('moveGuidance(button,-1)');assert.equal(r.run("parent.children.map(x=>x.name).join(',')"),'panel,first,second');});

test('pre-solved examples validate in every region without needing background search',()=>{const r=setup();r.run('render=()=>{};');for(const center of ['primaria','secundaria'])for(const region of r.run('REGIONS.map(r=>r.id)')){r.run('state=createExampleProject('+JSON.stringify(center)+','+JSON.stringify(region)+');fix()');assert.equal(r.run('applyExampleLayout()'),true,center+' '+region);assert.equal(r.run('allIssues().size'),0);assert.equal(r.run('state.lessons.filter(l=>l.day==null).length'),0);}});

test('timetable shows clock time separately from period counts',()=>{const r=setup();r.run("state.slots[0].end='08:45';state.activities=[act('a')];fix();Object.assign(state.lessons[0],{day:0,slot:0});ui.ht='G';ui.hid.G='g';");const html=r.run('vHor()');assert.match(html,/45 min · 1 tramo/);assert.doesNotMatch(html,/>1 h ·/);});
test('PDF exports select one or all entities without changing the project',()=>{const r=setup();r.run("state=createExampleProject('primaria','extremadura');fix();applyExampleLayout();");const before=r.run('JSON.stringify(state)');for(const type of ['G','T','R']){const ids=r.run('state[COLL['+JSON.stringify(type)+']].map(e=>e.id)');assert.equal(r.run('timetablePdfData('+JSON.stringify(type)+','+JSON.stringify(ids)+').entities.length'),ids.length);assert.equal(r.run('timetablePdfData('+JSON.stringify(type)+','+JSON.stringify([ids[0]])+').entities.length'),1);}assert.equal(r.run('JSON.stringify(state)'),before);});
test('PDF models keep multi-period lessons, conflicts, recesses and unplaced lessons visible',()=>{const r=setup();r.run("state.activities=[act('a',{dur:2}),act('b')];fix();Object.assign(state.lessons[0],{day:0,slot:0});state.slots.push({start:'11:00',end:'11:30',recreo:true});fix();");const data=r.run("timetablePdfData('G',['g'])");assert.match(data.entities[0].rows[1].cells[0].text,/Continuación/);assert.equal(data.entities[0].unplaced.length,1);assert.equal(data.entities[0].rows.at(-1).cells[0].text,'Recreo');assert.equal(data.draft,true);});
test('PDF rendering produces a real multi-page document for all groups',()=>{const {jsPDF}=require('./vendor/jspdf.umd.min.js');require('./vendor/jspdf.plugin.autotable.min.js').applyPlugin(jsPDF);const r=setup();r.box.window.jspdf={jsPDF};r.run("state=createExampleProject('primaria','extremadura');fix();applyExampleLayout();");const doc=r.run("createTimetablePdf(timetablePdfData('G',state.groups.map(g=>g.id)))");assert.ok(doc.getNumberOfPages()>=r.run('state.groups.length'));assert.ok(Buffer.from(doc.output('arraybuffer')).subarray(0,5).equals(Buffer.from('%PDF-')));});

